from decimal import Decimal, InvalidOperation
from typing import Any


def _numeric(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, bool):
        return Decimal(int(value))
    return Decimal(str(value).strip())


def _approve_allowed(record: dict) -> bool:
    try:
        return _numeric(record.get("TOT_AMT", "")) > Decimal("0")
    except (InvalidOperation, ValueError, TypeError):
        return False


def _account_credit_hold(record: dict, tables: dict) -> str:
    account_id = record.get("ACCT_ID", "")
    rows = tables.get("ACCT_MASTER", [])
    for row in rows:
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    new_record = dict(record)

    transitions = (
        ("E", "A", "approve"),
        ("A", "S", "ship"),
        ("S", "I", "invoice"),
        ("E", "X", "cancel"),
        ("A", "X", "cancel"),
        ("I", "X", "cancel"),
    )

    for from_state, to_state, transition_event in transitions:
        if state != from_state or event != transition_event:
            continue

        if from_state == "E" and event == "approve":
            if not _approve_allowed(record):
                continue
            return {
                "state": to_state,
                "record": new_record,
                "audits": ["ORD_APPR"],
                "notifies": [],
                "matched": True,
            }

        if from_state == "A" and event == "cancel":
            if _account_credit_hold(record, tables) == "Y":
                continue
            return {
                "state": to_state,
                "record": new_record,
                "audits": ["ORD_CANC"],
                "notifies": [],
                "matched": True,
            }

        if from_state == "A" and event == "ship":
            return {
                "state": to_state,
                "record": new_record,
                "audits": ["ORD_SHIP"],
                "notifies": ["shipped"],
                "matched": True,
            }

        if from_state == "S" and event == "invoice":
            return {
                "state": to_state,
                "record": new_record,
                "audits": ["ORD_INV"],
                "notifies": [],
                "matched": True,
            }

        if from_state == "E" and event == "cancel":
            return {
                "state": to_state,
                "record": new_record,
                "audits": ["ORD_CANC"],
                "notifies": [],
                "matched": True,
            }

        if from_state == "I" and event == "cancel":
            return {
                "state": to_state,
                "record": new_record,
                "audits": ["ORD_CANC_INV"],
                "notifies": ["credit_note"],
                "matched": True,
            }

    return {
        "state": state,
        "record": new_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
